// HexaCore · Software Supply Chain (SBOM).
// Software bills of materials (CycloneDX / SPDX) are ingested from vendor
// portals and the client's own build pipelines, or generated by binary scans
// of firmware, so "do we use it?" reaches libraries buried inside products.
//
// Library names are fictional open-source-style packages and every
// vulnerability id is a fictional CVE-2026-5xxxx id; products carrying
// vulnerable components come from fictional vendors. Real suppliers from the
// TPRM register only appear as SBOMs requested / missing, or as clean SBOMs.
//
// The headline component of each customer's Critical Vulnerability Response
// advisory is embedded in a handful of vendor products that the asset-level
// match does not see: the "hidden exposure" this module surfaces.
import type { CustomerId, CustomerProfile, Health, Severity } from '../types';
import { rng } from '../../lib/rng';
import { tpSuppliers } from './tprm';
import { vrAdvisory, vrAssets } from './vulnresponse';
import { forCustomer, type CustomerMap } from '../customerMap';

/* =====================================================================
   Types
   ===================================================================== */
export type SbFormat = 'CycloneDX 1.6' | 'CycloneDX 1.5' | 'SPDX 2.3' | 'SPDX 3.0';
export type SbSource = 'Vendor portal' | 'Build pipeline' | 'Generated by scan';
export type SbRequest = 'Not requested' | 'Requested' | 'Promised' | 'Declined';
export type SbVex = 'Affected' | 'Not affected' | 'Under investigation' | 'Fixed';
export type SbLicRisk = 'Permissive' | 'Weak copyleft' | 'Strong copyleft' | 'Unknown';
export type SbOrigin = 'Vendor' | 'In-house';
export type SbTag = 'device' | 'vehicle' | 'ship' | 'app' | 'ot' | 'payments';

export const SB_VEX: SbVex[] = ['Affected', 'Under investigation', 'Not affected', 'Fixed'];
export const SB_VEX_COLOR: Record<SbVex, string> = { Affected: 'var(--sev-critical)', 'Under investigation': 'var(--sev-medium)', 'Not affected': 'var(--good)', Fixed: 'var(--m-matrix)' };
export const SB_VEX_HEX: Record<SbVex, string> = { Affected: '#e0345e', 'Under investigation': '#f0a338', 'Not affected': '#2dd4bf', Fixed: '#a07cfb' };
export const SB_LIC_COLOR: Record<SbLicRisk, string> = { Permissive: 'var(--good)', 'Weak copyleft': 'var(--sev-low)', 'Strong copyleft': 'var(--sev-high)', Unknown: 'var(--sev-medium)' };
export const SB_REQ_COLOR: Record<SbRequest, string> = { 'Not requested': 'var(--text-muted)', Requested: 'var(--sev-medium)', Promised: 'var(--m-matrix)', Declined: 'var(--bad)' };
export const SB_SOURCE_HEX: Record<SbSource | 'Missing', string> = { 'Vendor portal': '#4f8cff', 'Build pipeline': '#2dd4bf', 'Generated by scan': '#a07cfb', Missing: '#e0345e' };
export const SB_STALE_DAYS = 90;

export interface SbVuln { id: string; sev: Severity; cvss: number; title: string; fixedIn: string; advisory?: boolean }
export interface SbComponent {
  id: string;
  name: string;
  ecosystem: string;
  category: string;
  licence: string;
  licRisk: SbLicRisk;
  latest: string;
  maintainer: string;
  desc: string;
  vulns: SbVuln[];
  /** The component behind the customer's headline advisory. */
  advisory?: boolean;
}
export interface SbLib { compId: string; version: string; vex: Record<string, SbVex>; via?: string }
export interface SbModule { name: string; version: string; libs: SbLib[] }
export interface SbSbom { format: SbFormat; source: SbSource; ageDays: number; signed: boolean; tool: string; serial: string }
export interface SbProduct {
  id: string;
  name: string;
  vendor: string;
  origin: SbOrigin;
  category: string;
  tenants: string[];
  tags: SbTag[];
  supplierName?: string;
  supplierId?: string;
  sbom: SbSbom | null;
  request: SbRequest;
  requestDaysAgo: number | null;
  componentCount: number;
  modules: SbModule[];
  instances: number;
  criticality: 1 | 2 | 3 | 4 | 5;
  adv?: 'matched' | 'hidden';
  note?: string;
}
export interface SbUsage { product: SbProduct; module: string; lib: SbLib }
export interface SbCompRow {
  c: SbComponent;
  uses: SbUsage[];
  products: number;
  versions: string[];
  /** Vulnerability instances (vuln × product) by VEX status. */
  vex: Record<SbVex, number>;
  maxSev: Severity | null;
  open: number;
  vulnerable: boolean;
  licFlag: boolean;
}
export interface SbReg { id: string; name: string; short: string; ask: string; scopeLabel: string; test: (p: SbProduct) => boolean }
export interface SbRegRow { reg: SbReg; inScope: SbProduct[]; withSbom: SbProduct[]; pct: number }

