/* =====================================================================
   Build (group-level, cached per customer)
   ===================================================================== */
interface Base { products: SbProduct[]; comps: SbComponent[]; byId: Map<string, SbComponent>; regs: SbReg[]; advComp: SbComponent }
const CACHE = new Map<CustomerId, Base>();

const FORMAT: Record<Exclude<Code, null | 'scan'>, SbFormat> = { c6: 'CycloneDX 1.6', c5: 'CycloneDX 1.5', s2: 'SPDX 2.3', s3: 'SPDX 3.0' };
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const conn = (c: CustomerProfile, re: RegExp) => c.connectors.find((k) => re.test(k.category));
const cname = (k?: { vendor: string; product: string }) => (k ? (k.vendor === 'Generic' || k.vendor === 'HexaShield' ? k.product : `${k.vendor} ${k.product}`) : '');

/** Which tool produced the SBOM for a given source. */
export function sbTool(c: CustomerProfile, src: SbSource, ot: boolean): string {
  if (src === 'Build pipeline') return cname(conn(c, /AppSec/)) || 'Build pipeline (CycloneDX plugin)';
  if (src === 'Generated by scan') return ot ? `HexaCore binary analysis${c.connectors.some((k) => k.category === 'OT') ? ` · ${cname(c.connectors.find((k) => k.category === 'OT'))}` : ''}` : `HexaCore binary analysis · ${cname(conn(c, /^Vulnerability$/)) || 'scanner'}`;
  return 'HexaCore SBOM intake · vendor portal';
}

function bumpDown(ver: string, r: ReturnType<typeof rng>): string {
  const m = ver.match(/^(.*?)(\d+)$/);
  if (!m) return ver;
  const n = Number(m[2]);
  return n > 0 ? `${m[1]}${Math.max(0, n - r.int(1, Math.min(3, n)))}` : ver;
}

function build(c: CustomerProfile): Base {
  const hit = CACHE.get(c.id);
  if (hit) return hit;
  const r = rng(`sbom-${c.id}`);
  const adv = vrAdvisory(c);
  const ac = forCustomer(ADV_COMP, c);
  const advComp: SbComponent = {
    id: slug(ac.name), name: ac.name, ecosystem: ac.ecosystem, category: ac.category, licence: ac.licence, licRisk: ac.licRisk, latest: ac.latest, maintainer: ac.maintainer ?? adv.vendor, desc: ac.desc, advisory: true,
    vulns: [{ id: adv.cve, sev: 'critical', cvss: adv.cvss, title: ac.vulnTitle, fixedIn: ac.latest, advisory: true }],
  };
  const comps: SbComponent[] = [advComp, ...[...GENERIC, ...forCustomer(SECTOR_LIBS, c)].map((s) => ({ ...s, id: slug(s.name), maintainer: s.maintainer ?? 'Open-source community', vulns: s.vulns ?? [] }))];
  const byId = new Map(comps.map((x) => [x.id, x]));
  const pool = comps.filter((x) => !x.advisory);
  const clean = pool.filter((x) => !x.vulns.length);
  const sups = tpSuppliers(c, 'all');
  const supId = (name?: string) => (name ? sups.find((s) => s.name === name)?.id : undefined);

  const pickVex = (pr: ReturnType<typeof rng>): SbVex => pr.weighted([['Affected', 3], ['Not affected', 4], ['Under investigation', 2], ['Fixed', 2]] as const);

  const products: SbProduct[] = forCustomer(PRODUCTS, c).map((s) => {
    const pr = rng(`sbom-${c.id}-${s.n}`);
    const origin: SbOrigin = s.o === 'I' ? 'In-house' : 'Vendor';
    const tags = s.tags ?? [];
    let sbom: SbSbom | null = null;
    if (s.s) {
      const source: SbSource = s.s === 'scan' ? 'Generated by scan' : origin === 'In-house' ? 'Build pipeline' : 'Vendor portal';
      const ageDays = source === 'Build pipeline' ? pr.int(0, 9) : source === 'Generated by scan' ? pr.int(3, 40) : pr.weighted([[pr.int(8, 60), 5], [pr.int(95, 240), 3]] as const);
      sbom = { format: s.s === 'scan' ? 'CycloneDX 1.6' : FORMAT[s.s], source, ageDays, signed: source === 'Build pipeline' ? true : pr.chance(0.55), tool: sbTool(c, source, tags.includes('ot')), serial: `urn:uuid:${pr.hex(8)}-${pr.hex(4)}-${pr.hex(4)}-${pr.hex(4)}-${pr.hex(12)}` };
    }
    // Dependency tree (only when an SBOM exists)
    const modules: SbModule[] = [];
    if (sbom) {
      const realSupplier = s.o === 'S';
      const libPool = realSupplier ? clean : pool;
      const modNames = s.mods ?? ['Core service', 'Web console', 'Update agent'];
      const used = new Set<string>();
      modNames.forEach((mn, mi) => {
        const n = pr.int(2, 4);
        const picks = pr.pickN(libPool.filter((x) => !used.has(x.id)), n);
        const libs: SbLib[] = picks.map((x) => {
          used.add(x.id);
          const vex: Record<string, SbVex> = {};
          let ver = x.latest;
          if (x.vulns.length) {
            const st = pickVex(pr);
            x.vulns.forEach((vv) => { vex[vv.id] = st; });
            ver = st === 'Fixed' ? x.vulns[0].fixedIn : bumpDown(x.vulns[0].fixedIn, pr);
          } else if (pr.chance(0.4)) ver = bumpDown(x.latest, pr);
          // a transitive dependency is sometimes pulled in through another library
          const via = mi > 0 && pr.chance(0.35) ? pr.pick(GENERIC.filter((g) => !g.vulns).map((g) => g.name)) : undefined;
          return { compId: x.id, version: ver, vex, via: via && via !== x.name ? via : undefined };
        });
        if (s.adv && mi === (s.adv === 'matched' ? 0 : modNames.length - 1)) {
          libs.unshift({ compId: advComp.id, version: s.advVer ?? adv.affectedVersions, vex: { [adv.cve]: s.advVex ?? 'Affected' } });
        }
        modules.push({ name: s.adv && mi === modNames.length - 1 && s.adv === 'hidden' ? `${mn} · ${ac.module}` : mn, version: `${pr.int(1, 9)}.${pr.int(0, 12)}.${pr.int(0, 20)}`, libs });
      });
    }
    return {
      id: `sb-${slug(s.n)}`.slice(0, 48), name: s.n, vendor: s.vendor, origin, category: s.cat, tenants: s.t, tags,
      supplierName: s.sup, supplierId: supId(s.sup), sbom,
      request: sbom ? 'Not requested' : (s.req ?? 'Not requested'), requestDaysAgo: sbom ? null : s.reqDays ?? null,
      componentCount: sbom ? (origin === 'In-house' ? r.int(380, 2400) : tags.includes('ot') || tags.includes('device') ? r.int(90, 620) : r.int(220, 1500)) : 0,
      modules, instances: s.inst ?? 1, criticality: s.crit ?? 3, adv: s.adv, note: s.note,
    };
  });

  const base: Base = { products, comps, byId, regs: forCustomer(REGS, c), advComp };
  CACHE.set(c.id, base);
  return base;
}

/* =====================================================================
   In-session store: SBOM requests sent from the page
   ===================================================================== */
const REQUESTED = new Map<string, number>(); // `${customer}:${productId}` -> epoch ms
const listeners = new Set<() => void>();
let version = 0;
export function sbSubscribe(l: () => void): () => void { listeners.add(l); return () => listeners.delete(l); }
export function sbVersion(): number { return version; }
export function sbRequestSbom(c: CustomerProfile, productId: string) {
  REQUESTED.set(`${c.id}:${productId}`, Date.now());
  version++;
  listeners.forEach((l) => l());
}

/* =====================================================================
   Public API
   ===================================================================== */
export interface SbData {
  products: SbProduct[];
  comps: SbCompRow[];
  regs: SbRegRow[];
  advComp: SbComponent;
  byId: Map<string, SbComponent>;
  kpi: {
    total: number; withSbom: number; missing: number; stale: number; fresh: number; freshPct: number; medianAge: number;
    tracked: number; vulnerable: number; suppressed: number; licence: number; vulnInstances: number;
  };
}

function median(a: number[]): number {
  if (!a.length) return 0;
  const s = [...a].sort((x, y) => x - y);
  return s[Math.floor(s.length / 2)];
}

const SEV_RANK: Record<Severity, number> = { critical: 4, high: 3, medium: 2, low: 1, info: 0 };

export function sbData(c: CustomerProfile, tenantId: string): SbData {
  const b = build(c);
  const products = b.products
    .filter((p) => tenantId === 'all' || p.tenants.includes(tenantId))
    .map((p) => {
      const at = REQUESTED.get(`${c.id}:${p.id}`);
      return at && !p.sbom ? { ...p, request: 'Requested' as SbRequest, requestDaysAgo: 0 } : p;
    });
  const uses = new Map<string, SbUsage[]>();
  products.forEach((p) => p.modules.forEach((m) => m.libs.forEach((l) => {
    const arr = uses.get(l.compId) ?? [];
    arr.push({ product: p, module: m.name, lib: l });
    uses.set(l.compId, arr);
  })));
  const comps: SbCompRow[] = b.comps
    .filter((x) => uses.has(x.id))
    .map((x) => {
      const u = uses.get(x.id)!;
      const vex: Record<SbVex, number> = { Affected: 0, 'Under investigation': 0, 'Not affected': 0, Fixed: 0 };
      u.forEach((us) => Object.values(us.lib.vex).forEach((s) => { vex[s]++; }));
      const open = vex.Affected + vex['Under investigation'];
      const maxSev = x.vulns.length ? x.vulns.reduce<Severity>((m, vv) => (SEV_RANK[vv.sev] > SEV_RANK[m] ? vv.sev : m), 'info') : null;
      const distributed = u.some((us) => us.product.origin === 'In-house' || us.product.tags.includes('vehicle'));
      return {
        c: x, uses: u, products: new Set(u.map((us) => us.product.id)).size, versions: [...new Set(u.map((us) => us.lib.version))],
        vex, maxSev, open, vulnerable: open > 0,
        licFlag: x.licRisk === 'Unknown' || (x.licRisk === 'Strong copyleft' && distributed),
      };
    });
  const withSb = products.filter((p) => p.sbom);
  const ages = withSb.map((p) => p.sbom!.ageDays);
  const stale = ages.filter((a) => a > SB_STALE_DAYS).length;
  const regs: SbRegRow[] = b.regs.map((reg) => {
    const inScope = products.filter(reg.test);
    const withSbom = inScope.filter((p) => p.sbom);
    return { reg, inScope, withSbom, pct: inScope.length ? Math.round((withSbom.length / inScope.length) * 100) : 100 };
  });
  return {
    products, comps, regs, advComp: b.advComp, byId: b.byId,
    kpi: {
      total: products.length, withSbom: withSb.length, missing: products.length - withSb.length, stale, fresh: withSb.length - stale,
      freshPct: withSb.length ? Math.round(((withSb.length - stale) / withSb.length) * 100) : 0, medianAge: median(ages),
      tracked: Math.round(withSb.reduce((s, p) => s + p.componentCount, 0) * 0.46),
      vulnerable: comps.filter((x) => x.vulnerable).length,
      suppressed: comps.reduce((s, x) => s + x.vex['Not affected'], 0),
      licence: comps.filter((x) => x.licFlag).length,
      vulnInstances: comps.reduce((s, x) => s + x.vex.Affected + x.vex['Under investigation'] + x.vex['Not affected'] + x.vex.Fixed, 0),
    },
  };
}

export function sbProduct(d: SbData, id: string | null): SbProduct | undefined {
  return id ? d.products.find((p) => p.id === id) : undefined;
}
export function sbComp(d: SbData, id: string | null): SbCompRow | undefined {
  return id ? d.comps.find((x) => x.c.id === id) : undefined;
}

/** Vulnerable libraries in a product (VEX affected or under investigation). */
export function sbProductVulns(p: SbProduct, byId: Map<string, SbComponent>): { comp: SbComponent; lib: SbLib; module: string; vex: SbVex; vuln: SbVuln }[] {
  const out: { comp: SbComponent; lib: SbLib; module: string; vex: SbVex; vuln: SbVuln }[] = [];
  p.modules.forEach((m) => m.libs.forEach((l) => {
    const comp = byId.get(l.compId);
    if (!comp) return;
    comp.vulns.forEach((vv) => { const s = l.vex[vv.id]; if (s) out.push({ comp, lib: l, module: m.name, vex: s, vuln: vv }); });
  }));
  return out;
}

/* =====================================================================
   Hidden exposure for the headline advisory
   ===================================================================== */
export interface SbAdvExposure {
  cve: string;
  advId: string;
  advProduct: string;
  vendor: string;
  comp: SbComponent;
  matched: SbProduct[];
  hidden: SbProduct[];
  hiddenInstances: number;
  assetMatched: number;
}

/** Products whose SBOM contains the component behind the headline advisory. Null when `cve` is not the headline. */
export function sbAdvisoryExposure(c: CustomerProfile, tenantId: string, cve?: string): SbAdvExposure | null {
  const adv = vrAdvisory(c);
  if (cve && cve !== adv.cve) return null;
  const d = sbData(c, tenantId);
  const inside = d.products.filter((p) => p.modules.some((m) => m.libs.some((l) => l.compId === d.advComp.id)));
  const hidden = inside.filter((p) => p.adv === 'hidden');
  return {
    cve: adv.cve, advId: adv.id, advProduct: adv.product, vendor: adv.vendor, comp: d.advComp,
    matched: inside.filter((p) => p.adv === 'matched'), hidden,
    hiddenInstances: hidden.reduce((s, p) => s + p.instances, 0),
    assetMatched: vrAssets(c, tenantId, adv).length,
  };
}

/** Where a product sits in a component: module and lib. */
export function sbUsageOf(p: SbProduct, compId: string): { module: string; lib: SbLib } | undefined {
  for (const m of p.modules) for (const l of m.libs) if (l.compId === compId) return { module: m.name, lib: l };
  return undefined;
}

export function sbSources(c: CustomerProfile): { name: string; status?: Health }[] {
  const appsec = conn(c, /AppSec/);
  const ot = c.connectors.find((k) => k.category === 'OT');
  return [
    { name: 'HexaCore SBOM intake' },
    { name: appsec ? cname(appsec) : 'Build pipeline plugin' },
    { name: cname(conn(c, /^Vulnerability$/)) || 'Scanner' },
    ...(ot ? [{ name: cname(ot) }] : []),
    { name: 'HexaComply TPRM' },
  ];
}
